function t(){for(let e of Array.from(document.querySelectorAll("article img"))){if(e.dataset.imageLoadingBound==="true")continue;if(e.dataset.imageLoadingBound="true",e.complete&&e.naturalWidth>0){e.classList.remove("image-loading");continue}e.classList.add("image-loading");let n=()=>e.classList.remove("image-loading");e.addEventListener("load",n,{once:!0}),e.addEventListener("error",n,{once:!0}),typeof window.addCleanup=="function"&&window.addCleanup(()=>{e.removeEventListener("load",n),e.removeEventListener("error",n),e.classList.remove("image-loading")})}}document.addEventListener("nav",t);document.addEventListener("render",t);t();
